function Toast({msg}:{msg:string}){return msg?<div className="toast">{msg}</div>:null}
const CODE128B_PATTERNS=['212222','222122','222221','121223','121322','131222','122213','122312','132212','221213','221312','231212','112232','122132','122231','113222','123122','123221','223211','221132','221231','213212','223112','312131','311222','321122','321221','312212','322112','322211','212123','212321','232121','111323','131123','131321','112313','132113','132311','211313','231113','231311','112133','112331','132131','113123','113321','133121','313121','211331','231131','213113','213311','213131','311123','311321','331121','312113','312311','332111','314111','221411','431111','111224','111422','121124','121421','141122','141221','112214','112412','122114','122411','142112','142211','241211','221114','413111','241112','134111','111242','121142','121241','114212','124112','124211','411212','421112','421211','212141','214121','412121','111143','111341','131141','114113','114311','411113','411311','113141','114131','311141','411131','211412','211214','211232','2331112'];
function Barcode({value}:{value:string}){const text=String(value||'');if(!text)return null;const codes=[104,...Array.from(text).map(ch=>Math.max(0,ch.charCodeAt(0)-32))];let checksum=104;for(let i=1;i<codes.length;i++)checksum+=codes[i]*i;codes.push(checksum%103,106);let x=8;const bars:any[]=[];codes.forEach(code=>{const pattern=CODE128B_PATTERNS[code]||'';let black=true;for(const w of pattern.split('').map(Number)){if(black)bars.push(<rect key={x} x={x} y="4" width={w*1.35} height="34" rx=".3"/>);x+=w*1.35;black=!black}});return <svg className="orderBarcode" viewBox={`0 0 ${x+8} 54`} role="img" aria-label={`Barcode ${text}`}><g>{bars}</g><text x={(x+8)/2} y="50" textAnchor="middle">{text}</text></svg>}
function BarcodeScanner({onDetected,onClose}:{onDetected:(value:string)=>void;onClose:()=>void}){
 const videoRef=React.useRef<HTMLVideoElement|null>(null),streamRef=React.useRef<MediaStream|null>(null),zxingRef=React.useRef<any>(null);
 const [error,setError]=useState(''),[manual,setManual]=useState(''),[starting,setStarting]=useState(false),[ready,setReady]=useState(false);
 const stop=useCallback(()=>{streamRef.current?.getTracks().forEach(t=>t.stop());streamRef.current=null;try{zxingRef.current?.reset()}catch{}zxingRef.current=null},[]);
 const start=useCallback(async()=>{
  if(starting||ready)return;setStarting(true);setError('');
  try{
   if(!window.isSecureContext){throw new Error('Camera access requires HTTPS. Open the deployed HTTPS site, not an HTTP address.');}
   if(!navigator.mediaDevices?.getUserMedia){throw new Error('This installed app cannot access the camera. Update iOS/Safari and make sure camera access is allowed for YN Studio.');}
   const Detector=(window as any).BarcodeDetector;
   if(Detector){
    const detector=new Detector({formats:['code_128','ean_13','ean_8','upc_a','upc_e','qr_code']});
    const stream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}}});
    streamRef.current=stream;if(videoRef.current){videoRef.current.srcObject=stream;await videoRef.current.play()}
    setReady(true);
    const loop=async()=>{if(!videoRef.current||!streamRef.current)return;try{const hits=await detector.detect(videoRef.current);const value=hits?.[0]?.rawValue;if(value){stop();onDetected(value);return}}catch{}requestAnimationFrame(loop)};requestAnimationFrame(loop);return;
   }
   const {BrowserMultiFormatReader}=await import('@zxing/browser');
   const reader=new BrowserMultiFormatReader();zxingRef.current=reader;
   if(!videoRef.current)throw new Error('Camera preview is not ready.');
   setReady(true);
   await reader.decodeFromConstraints({audio:false,video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}}},videoRef.current,(result:any,err:any)=>{if(result?.getText?.()){const value=result.getText();stop();onDetected(value)}});
  }catch(e:any){setReady(false);setError(e?.name==='NotAllowedError'?'Camera permission was denied. In your phone settings, allow camera access for YN Studio, then try again.':e?.message||'Unable to access the camera.');stop()}
  finally{setStarting(false)}
 },[onDetected,ready,starting,stop]);
 useEffect(()=>()=>stop(),[stop]);
 return <div className="scannerOverlay"><div className="scannerCard"><div className="scannerHead"><div><span className="eyebrow">FAST SCAN</span><h2>Scan package barcode</h2><p>Use the camera to scan the barcode printed on the package.</p></div><button className="icon" onClick={()=>{stop();onClose()}}><X/></button></div><div className="scannerViewport">{error?<div className="scannerFallback"><Camera/><b>Camera unavailable</b><small>{error}</small><button onClick={start} disabled={starting}><Camera/>{starting?'Opening camera…':'Try camera again'}</button></div>:<><video ref={videoRef} playsInline muted autoPlay/><span className="scanFrame"/>{!ready&&<div className="scannerStart"><Camera/><b>Ready to scan</b><small>Tap below to open the camera. This also works when YN Studio is installed as a PWA.</small><button onClick={start} disabled={starting}>{starting?'Opening camera…':'Open camera'}</button></div>}</>}</div><div className="scannerManual"><input value={manual} onChange={e=>setManual(e.target.value)} placeholder="Enter order number, e.g. YN-12345678"/><button onClick={()=>manual.trim()&&onDetected(manual.trim())}><Search/> Find</button></div></div></div>
}
