function LoaderSplash(){const c=useLoaderCfg();const loc=useLocation();const[boot,setBoot]=useState(true),[busy,setBusy]=useState(false);useEffect(()=>{const t=window.setTimeout(()=>setBoot(false),1400);const a=()=>setBusy(true),b=()=>setBusy(false);window.addEventListener('yn-loading-start',a);window.addEventListener('yn-loading-stop',b);return()=>{window.clearTimeout(t);window.removeEventListener('yn-loading-start',a);window.removeEventListener('yn-loading-stop',b)}},[]);const has=!!(c.loader_image||c.loader_text)&&!loc.pathname.startsWith('/admin');const vis=has&&(boot||busy);if(!has)return null;return <div className={'ynSplash'+(vis?' show':'')} style={{background:c.loader_bg||'#ffffff'}} aria-hidden={!vis}>{c.loader_image&&<img src={c.loader_image} alt="" style={{width:Number(c.loader_size||120),maxWidth:'70vw'}}/>}{c.loader_text&&<b>{c.loader_text}</b>}</div>}
function GlobalLoading(){const[show,setShow]=useState(false);const loc=useLocation();useEffect(()=>{const start=()=>setShow(true),stop=()=>setShow(false);window.addEventListener('yn-loading-start',start);window.addEventListener('yn-loading-stop',stop);return()=>{window.removeEventListener('yn-loading-start',start);window.removeEventListener('yn-loading-stop',stop)}},[]);useEffect(()=>{setShow(true);const t=window.setTimeout(()=>setShow(false),360);return()=>window.clearTimeout(t)},[loc.pathname]);return <><LoaderSplash/><div className={'globalLoader '+(show?'show':'')} aria-hidden={!show}><span/></div></>}
