/* Snack orders (every item is a Snacks-page product) follow their own status flow:
   paid -> processing -> waiting for a delivery driver -> out for delivery -> completed / cancelled */
const spCache=new Map<string,string|null>();
async function snackOrderIds(list:{id:string,items:any[]}[]):Promise<Set<string>>{
  const need=[...new Set(list.flatMap(o=>o.items.map((i:any)=>i.product_id)).filter((id:any)=>id&&!spCache.has(id)))] as string[];
  if(need.length){const r=await supabase.from('products').select('id,store_page').in('id',need);for(const q of (r.data||[]) as any[])spCache.set(q.id,q.store_page||null);for(const id of need)if(!spCache.has(id))spCache.set(id,null)}
  return new Set(list.filter(o=>o.items.length>0&&o.items.every((i:any)=>spCache.get(i.product_id)==='snacks')).map(o=>o.id));
}
function orderStage(s:string,snack=false){
  const n=String(s||'').toLowerCase();
  if(/cancel|reject|fail/.test(n))return{k:'cancelled',step:-1,place:''};
  if(/complet|^delivered$/.test(n))return{k:'done',step:snack?4:5,place:''};
  if(snack){
    if(/driver|rider|courier|pick.?up/.test(n))return{k:'driver',step:2,place:''};
    if(/out for|deliver|on the way|transit|ship/.test(n))return{k:'moto',step:3,place:''};
    if(/pending|unpaid|waiting/.test(n))return{k:'wait',step:-1,place:''};
    if(/process|prepar|pack|confirm/.test(n))return{k:'box',step:1,place:''};
    return{k:'box',step:0,place:''};
  }
  if(/pending|unpaid|waiting/.test(n))return{k:'wait',step:-1,place:''};
  const place=/cambodia/.test(n)?'cambodia':/china/.test(n)?'china':'';
  if(/arriv/.test(n))return{k:'warehouse',step:place==='cambodia'?3:1,place:place||'china'};
  if(/left|leav|ship|transit|out for/.test(n))return{k:'truck',step:place==='china'?2:4,place:place||'cambodia'};
  return{k:'box',step:0,place:''};
}
