 useEffect(()=>{(async()=>{setCats((await supabase.from('categories').select('*').eq('status','active')).data||[]);if(!id)return;const p=(await supabase.from('products').select('*').eq('id',id).single()).data;if(!p)return;setName(p.name||'');setDesc(p.description||'');setPrice(String(p.price??''));setOrig(p.original_price==null?'':String(p.original_price));setSku(p.sku||'');setCat(p.category_id||'');setExistingImgs((await supabase.from('product_images').select('id,image_url,sort_order').eq('product_id',id).order('sort_order')).data||[]);const os=(await supabase.from('product_options').select('*').eq('product_id',id).order('sort_order')).data||[];for(const o of os){const vs=(await supabase.from('product_option_values').select('*').eq('option_id',o.id).order('sort_order')).data||[];o.values=vs.map((v:any)=>({value:v.value,price:String(v.price_adjustment||''),imageFile:null,image_url:v.image_url||''}))}if(os.length)setOpts(os)})()},[id]);
