 const nav=useNavigate(),[d,setD]=useState<any>(null),[tx,setTx]=useState<any[]>([]),[pay,setPay]=useState(''),[method,setMethod]=useState<'wallet'|'qr'>('wallet'),[qrAmount,setQrAmount]=useState(''),[bkPay,setBkPay]=useState<any>(null),bkOn=useBakongEnabled(),[requests,setRequests]=useState<any[]>([]),[accts,setAccts]=useState<any[]>([]),[curTab,setCurTab]=useState('USD'),[busy,setBusy]=useState(false),[msg,setMsg]=useState('');const payRef=useRef(false),holdRef=useRef(false);payRef.current=!!bkPay;
 async function load(want?:string){const u=await uid();if(!u)return;const interestResult=await supabase.rpc('accrue_customer_debt_interest',{p_user_id:u});if(interestResult.error)console.warn('Debt interest update:',interestResult.error.message);const daResult=await supabase.from('debt_accounts').select('*').eq('user_id',u).eq('enabled',true).gt('current_balance',0).order('currency',{ascending:false});if(daResult.error){setD(null);setMsg(daResult.error.message);return}const list=daResult.data||[];if(!list.length){if(payRef.current||holdRef.current)return;setD(null);nav('/',{replace:true});return}setAccts(list);const da=list.find((x:any)=>x.currency===(want||curTab))||list[0];setCurTab(da.currency||'USD');setD(da);const txResult=await supabase.from('debt_transactions').select('*').eq('debt_account_id',da.id).order('created_at',{ascending:false}).limit(500);if(txResult.error)console.warn('Debt history:',txResult.error.message);setTx((txResult.data||[]).filter((x:any)=>x.archived!==true));const rr=await supabase.from('debt_payment_requests').select('*').eq('debt_account_id',da.id).order('submitted_at',{ascending:false}).limit(20);if(!rr.error)setRequests((rr.data||[]).filter((r:any)=>!da.cycle_started_at||new Date(r.submitted_at)>=new Date(da.cycle_started_at)))}
 useEffect(()=>{load()},[]);useEffect(()=>{if(!bkOn)return;let live=true;const run=async()=>{try{const j=await bakongCall('/api/bakong/sync');if(live&&j?.updated>0)load()}catch{}};run();const t=window.setInterval(run,8000);const vis=()=>{if(document.visibilityState==='visible')run()};document.addEventListener('visibilitychange',vis);return()=>{live=false;window.clearInterval(t);document.removeEventListener('visibilitychange',vis)}},[bkOn]);
 async function makeWalletPayment(){const n=Number(pay);if(!n||n<=0)return setMsg('Enter a valid payment amount.');if(n>Number(d.current_balance))return setMsg('Payment cannot be greater than your current debt.');setBusy(true);const r=await supabase.rpc('customer_pay_debt',{p_amount:n});setBusy(false);if(r.error)return setMsg(r.error.message);setPay('');setMsg('Wallet payment recorded successfully.');await load()}
 function startKhqr(){const n=Math.round(Number(qrAmount)*100)/100;if(!n||n<=0)return setMsg('Enter a valid payment amount.');if(n>Number(d.current_balance))return setMsg('Payment cannot be greater than your current debt.');setMsg('');setBkPay({kind:'debt',amount:n,balance:Number(d.current_balance)})}
 if(!d)return <><main className="shop"><Top title="Debt" back/><section className="debtEmptyCard"><div className="debtEmptyIcon"><CreditCard/></div><h2>No debt account</h2><p>You currently have no enabled outstanding debt.</p></section></main><Nav/></>;
