 function choose(x:any){setSelected(x);setAddCur(x.currency||'USD');setForm({user_id:x.user_id,currency:x.currency||'USD',original_debt:String(x.current_balance??x.original_debt??''),start_date:x.start_date||'',end_date:x.end_date||'',interest_type:x.interest_type||'percent',interest_value:String(x.interest_value??0),enabled:!!x.enabled});setPayment('');setNote('');setAddAmount('');setAddDate(new Date().toISOString().slice(0,10));setAddNote('');loadHistory(x.id)}
 function newDebt(){setSelected(null);setHistory([]);setForm({user_id:'',currency:'USD',original_debt:'',start_date:new Date().toISOString().slice(0,10),end_date:'',interest_type:'percent',interest_value:'0',enabled:true});setPayment('');setNote('');setAddAmount('')}
 async function save(){if(!form.user_id)return alert('Choose a customer.');if(!selected&&accounts.some((x:any)=>x.user_id===form.user_id&&(x.currency||'USD')===form.currency))return alert('This customer already has a '+(form.currency==='KHR'?'riel':'dollar')+' debt account. Select it in the list and use Add new debt.');const amount=Number(form.original_debt),interest=Number(form.interest_value);if(!Number.isFinite(amount)||amount<0)return alert('Enter a valid amount owed.');if(!Number.isFinite(interest)||interest<0)return alert('Enter a valid interest value.');if(form.start_date&&form.end_date&&form.end_date<form.start_date)return alert('End date cannot be before start date.');setBusy(true);const r=await supabase.rpc('admin_upsert_debt',{p_user_id:form.user_id,p_original_debt:amount,p_interest_type:form.interest_type,p_interest_value:interest,p_enabled:form.enabled,p_account_id:selected?.id||null,p_start_date:form.start_date||null,p_end_date:form.end_date||null,p_currency:form.currency||'USD'});setBusy(false);if(r.error)return alert(r.error.message);await load();const id=r.data?.id;if(id){const fresh=(await supabase.from('debt_accounts').select('*').eq('id',id).single()).data;if(fresh){const profile=customers.find(x=>x.user_id===fresh.user_id);choose({...fresh,profile})}}else newDebt()}
