 async function deleteDebt(x:any){const who=x.profile?.name||x.profile?.email||'this customer',owes=Number(x.current_balance||0)>0?`\n\nThey still owe ${fmtCur(x.current_balance,x.currency)} - that debt will be erased.`:'';if(!confirm(`Completely delete the ${x.currency==='KHR'?'riel':'dollar'} debt of ${who}?${owes}\n\nThe account, its full history and its QR receipts are removed for good and cannot be brought back.`))return;setBusy(true);const rq=await supabase.from('debt_payment_requests').select('receipt_path').eq('debt_account_id',x.id);const paths=(rq.data||[]).map((r:any)=>r.receipt_path).filter(Boolean);if(paths.length)await supabase.storage.from('debt-receipts').remove(paths);const r=await supabase.rpc('admin_delete_debt',{p_debt_account_id:x.id});setBusy(false);if(r.error)return alert('Delete failed: '+r.error.message+'\n\nRun supabase-debt-delete-and-fresh-start.sql in Supabase first.');setSelected(null);setHistory([]);newDebt();await load()}
