 async function loadCoupons(){setCoupons((await supabase.from('coupons').select('*').eq('active',true).order('created_at',{ascending:false})).data||[])}
 useEffect(()=>{load();loadCoupons()},[]);useEffect(()=>{if(!active){setMessages([]);return}loadMessages(active.id);const channel=supabase.channel('support-admin-'+active.id).on('postgres_changes',{event:'*',schema:'public',table:'support_messages',filter:`ticket_id=eq.${active.id}`},()=>loadMessages(active.id)).on('postgres_changes',{event:'*',schema:'public',table:'chat_rewards',filter:`ticket_id=eq.${active.id}`},()=>loadMessages(active.id)).subscribe();return()=>{supabase.removeChannel(channel)}},[active?.id]);
 async function uploadChatFile(f:File){const u=await uid();if(!u)return null;const path=`${u}/${crypto.randomUUID()}-${f.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const r=await supabase.storage.from('support-chat').upload(path,f,{upsert:false});if(r.error)throw r.error;return supabase.storage.from('support-chat').getPublicUrl(path).data.publicUrl}
